pub fn insert(&mut self, key: usize, value: V) -> Option<V> {
    if key >= self.v.len() {
        self.v.resize_with(key + 1, || None);
    }
    let result = std::mem::replace(&mut self.v[key], Some(value));
    if result.is_none() {
        self.n += 1;
    }
    result
}

